// Some portions generated by Codex
// Some portions generated by Claude
/**
 * What the statement card shows about one statement (an edge): its predicate (description, domain, range, how often
 * it is used) and what the repository says about the statement itself: RDF 1.2 reifiers (`?r rdf:reifies <<( s p o
 * )>>`, written `<< s p o >>` or `{| … |}` in Turtle), classic reifications (`rdf:Statement` with `rdf:subject`,
 * `rdf:predicate`, `rdf:object`), and statements whose object is the triple term itself.
 */
import type { Binding, SparqlValue } from "./explorer-types.ts";
import type { GraphEdge } from "./graph-types.ts";
import { sparqlFacetValueToken } from "./rdf-terms.ts";
import { iriToken, scoped, type GraphScope } from "./rdf-vocabulary.ts";

const RDF = "http://www.w3.org/1999/02/22-rdf-syntax-ns#";
const RDFS = "http://www.w3.org/2000/01/rdf-schema#";
const OWL = "http://www.w3.org/2002/07/owl#";
const SKOS = "http://www.w3.org/2004/02/skos/core#";
const SCHEMA = "http://schema.org/";
const DCTERMS = "http://purl.org/dc/terms/";

/** A statement as SPARQL tokens. */
export type StatementTokens = { subject: string; predicate: string; object: string };

/** The edge's statement as SPARQL tokens; null when its subject or object cannot be safely named in a later query. */
export function statementTokens(edge: Pick<GraphEdge, "source" | "predicate" | "target">): StatementTokens | null {
  // Ordinary _:label is query-local and cannot name an existing repository node. Fixed-node reference syntax
  // such as Jena <_:id> is in progress in RDF4J; switch after support merges, preserving server/repository
  // identity, then enable blank-node statement details alongside expansion, lookup and loaded-statement exclusions.
  const subject = sparqlFacetValueToken(edge.source);
  const predicate = sparqlFacetValueToken(edge.predicate);
  const object = sparqlFacetValueToken(edge.target);
  return subject && predicate && object && !subject.startsWith('"') ? { subject, predicate, object } : null;
}

/**
 * Everything the repository says about the statement, one row per (kind, about, property, value): kind "reifier"
 * (RDF 1.2), "reification" (classic) or "reference" (the triple term as an object; ?value is unbound). Without
 * `tripleTerms`, for stores that do not parse `<<( … )>>`, only classic reifications are asked for.
 */
export function statementAnnotationsQuery(statement: StatementTokens, scope: GraphScope, tripleTerms: boolean) {
  const { subject, predicate, object } = statement;
  const tripleTerm = `<<( ${subject} ${predicate} ${object} )>>`;
  const branches = [
    `{ BIND("reification" AS ?kind)
 ${scoped(`?about <${RDF}subject> ${subject} ; <${RDF}predicate> ${predicate} ; <${RDF}object> ${object} .`, scope)}
 OPTIONAL { ${scoped(`?about ?property ?value .
 FILTER(?property NOT IN (<${RDF}subject>, <${RDF}predicate>, <${RDF}object>) && (?property != <${RDF}type> || ?value != <${RDF}Statement>))`, scope, "__annotationGraph")} } }`,
  ];
  if (tripleTerms)
    branches.unshift(
      `{ BIND("reifier" AS ?kind)
 ${scoped(`?about <${RDF}reifies> ${tripleTerm} .`, scope)}
 OPTIONAL { ${scoped(`?about ?property ?value . FILTER(?property != <${RDF}reifies>)`, scope, "__annotationGraph")} } }`,
    );
  if (tripleTerms)
    branches.push(
      `{ BIND("reference" AS ?kind)
 ${scoped(`?about ?property ${tripleTerm} .`, scope)}
 FILTER(?property != <${RDF}reifies>) }`,
    );
  return `SELECT DISTINCT ?kind ?about ?property ?value WHERE {\n${branches.join("\nUNION\n")}\n} LIMIT 500`;
}

const PREDICATE_PROPERTIES = [
  `${RDFS}comment`,
  `${SKOS}definition`,
  `${SCHEMA}description`,
  `${DCTERMS}description`,
  `${RDFS}domain`,
  `${SCHEMA}domainIncludes`,
  `${RDFS}range`,
  `${SCHEMA}rangeIncludes`,
  `${RDFS}subPropertyOf`,
  `${OWL}inverseOf`,
];

/** What the repository says about a predicate: its description, domain, range, super-properties and inverse. */
export function predicateInfoQuery(predicate: string, scope: GraphScope) {
  return `SELECT DISTINCT ?property ?value WHERE {
 VALUES ?property { ${PREDICATE_PROPERTIES.map(iriToken).join(" ")} }
 ${scoped(`${iriToken(predicate)} ?property ?value .`, scope)}
} LIMIT 100`;
}

/** How many statements use the predicate (each once, whichever graphs hold it), counted up to `cap + 1`. */
export function predicateUsageQuery(predicate: string, cap: number, scope: GraphScope) {
  if (!Number.isInteger(cap) || cap < 1) throw new Error("Invalid usage cap.");
  return `SELECT (COUNT(*) AS ?uses) WHERE { { SELECT DISTINCT ?subject ?object WHERE { ${scoped(`?subject ${iriToken(predicate)} ?object .`, scope)} } LIMIT ${cap + 1} } }`;
}

export type PredicateInfo = {
  descriptions: Array<{ text: string; language: string; direction?: "ltr" | "rtl" }>;
  domain: string[];
  range: string[];
  superProperties: string[];
  inverse: string[];
};

/** The rows of predicateInfoQuery, sorted into what the card shows. */
export function predicateInfo(rows: readonly Binding[]): PredicateInfo {
  const info: PredicateInfo = { descriptions: [], domain: [], range: [], superProperties: [], inverse: [] };
  const add = (list: string[], value: string) => {
    if (!list.includes(value)) list.push(value);
  };
  for (const row of rows) {
    const property = row.property?.value;
    const value = row.value;
    if (!property || !value) continue;
    if (value.type === "literal" || value.type === "typed-literal") {
      if ([`${RDFS}comment`, `${SKOS}definition`, `${SCHEMA}description`, `${DCTERMS}description`].includes(property))
        info.descriptions.push({
          text: value.value,
          language: value["xml:lang"] ?? "",
          ...(value["its:dir"] ? { direction: value["its:dir"] } : {}),
        });
    } else if (value.type === "uri") {
      if (property === `${RDFS}domain` || property === `${SCHEMA}domainIncludes`) add(info.domain, value.value);
      else if (property === `${RDFS}range` || property === `${SCHEMA}rangeIncludes`) add(info.range, value.value);
      else if (property === `${RDFS}subPropertyOf`) add(info.superProperties, value.value);
      else if (property === `${OWL}inverseOf`) add(info.inverse, value.value);
    }
  }
  return info;
}

export type StatementCardKind = "reifier" | "reification" | "reference";

/** One resource that says something about the statement, and what it says. */
export type StatementCard = {
  kind: StatementCardKind;
  about: SparqlValue;
  /** The resource's own statements (for a reference: the one predicate that points at the statement, no value). */
  rows: Array<{ property: string; value?: SparqlValue }>;
};

const KIND_ORDER: Record<StatementCardKind, number> = { reifier: 0, reification: 1, reference: 2 };

/** The rows of statementAnnotationsQuery as one card per resource: reifiers, then reifications, then references. */
export function statementCards(rows: readonly Binding[]): StatementCard[] {
  const cards = new Map<string, StatementCard>();
  for (const row of rows) {
    const kind = row.kind?.value as StatementCardKind | undefined;
    const about = row.about;
    if (!about || (kind !== "reifier" && kind !== "reification" && kind !== "reference")) continue;
    const key = JSON.stringify([kind, about.type, about.value]);
    let card = cards.get(key);
    if (!card) cards.set(key, (card = { kind, about, rows: [] }));
    const property = row.property?.value;
    if (property) card.rows.push(row.value ? { property, value: row.value } : { property });
  }
  return [...cards.values()].sort((left, right) => KIND_ORDER[left.kind] - KIND_ORDER[right.kind]);
}
